import{_ as a,o as p,a as n,b as l}from"./app.C41L12d5.js";const c="/ascendc.github.io/assets/Fixpipe_NZ2NZ.DbS6KQWz.png",e="/ascendc.github.io/assets/Fixpipe_NZ2NZ_950.B9k4D7Jx.png",Z=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵搬出关键特性说明","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/cube_store_key_features"},{"text":"NZ2NZ","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/NZ2NZ"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/NZ2NZ.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/NZ2NZ.md","outlineHeaders":[{"level":2,"title":"特性说明","slug":"特性说明","link":"#特性说明"},{"level":2,"title":"特性约束","slug":"特性约束","link":"#特性约束"},{"level":2,"title":"使用示例","slug":"使用示例","link":"#使用示例"}],"lastUpdated":1786949923000}'),i={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/NZ2NZ.md"};function t(d,s,_,o,r,w){return p(),n("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>NZ2NZ<span id="ZH-CN_TOPIC_0000002538231204"></span></h1><h2 id="特性说明">特性说明<a class="header-anchor" href="#特性说明">​</a></h2><p>矩阵计算的搬出过程中NZ2NZ的核心功能体现为，矩阵计算结果搬出前后保持NZ数据排布不变。</p><div data-filter="A3,910b"><p>以如下产品型号为例：</p><div data-filter="A3"><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品</p></div><div data-filter="910b"><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品</p></div><p>NZ2NZ转化过程可以参考以下伪代码：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="n">j</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">j</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">mSize</span><span class="p">;</span><span class="w"> </span><span class="n">j</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">src_temp_n_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">src</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">j</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">L0C_element</span><span class="p">)</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="p">;</span>
<span class="w">    </span><span class="n">dst_temp_n_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">dst</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">j</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">DST_element</span><span class="p">);</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="n">k</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">k</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">ceil</span><span class="p">(</span><span class="n">nSize</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="mi">16</span><span class="p">);</span><span class="w"> </span><span class="n">k</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">src_block_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">src_temp_n_addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">k</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">srcStride</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">L0C_element</span><span class="p">)</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="p">;</span>
<span class="w">        </span><span class="n">dst_block_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">dst_temp_n_addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">k</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">dstStride</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">32</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>伪代码使用的参数具体说明如下：</p><ul><li>src表示源操作数搬运的起始地址。</li><li>dst表示目的操作数搬运的起始地址。</li><li>源操作数中NZ矩阵每一行的起始地址为src_temp_n_addr。</li><li>目的操作数中NZ矩阵每一行的起始地址为dst_temp_n_addr。</li><li>在每一行中，以16个数据为粒度进行数据块切分，源操作数每一块数据块的起始地址为src_block_addr，目的操作数中每一数据块起始地址为dst_block_addr。</li></ul><p>以下参数为NZ2NZ用户可配置参数，含义及取值范围参见<a href="../cube_compute_store/Fixpipe_L0CToGM.html">Fixpipe搬运参数</a>：</p><ul><li>mSize与nSize分别表示矩阵M方向和N方向上的维度。</li><li>srcStride表示源NZ矩阵中不同Z分形列的间隔，单位为C0_Size（C0_Size=16*sizeof(T)，T为操作数的数据类型）。</li><li>dstStride表示目标NZ矩阵中不同Z分形列的间隔，单位为32字节。</li></ul></div><div data-filter="950"><p>以Ascend 950PR/Ascend 950DT为例，NZ2NZ转化过程可以参考以下伪代码：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="n">j</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">j</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">mSize</span><span class="p">;</span><span class="w"> </span><span class="n">j</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">src_temp_n_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">src</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">j</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">L0C_element</span><span class="p">)</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="p">;</span>
<span class="w">    </span><span class="n">dst_temp_n_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">dst</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">j</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">DST_element</span><span class="p">);</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="n">k</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">k</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">ceil</span><span class="p">(</span><span class="n">nSize</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="mi">16</span><span class="p">);</span><span class="w"> </span><span class="n">k</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">src_block_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">src_temp_n_addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">k</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">srcStride</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">L0C_element</span><span class="p">)</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="p">;</span>
<span class="w">        </span><span class="n">dst_block_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">dst_temp_n_addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">k</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">dstStride</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">DST_element</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>伪代码使用的参数具体说明如下：</p><ul><li>src表示源操作数搬运的起始地址。</li><li>dst表示目的操作数搬运的起始地址。</li><li>源操作数中NZ矩阵每一行的起始地址为src_temp_n_addr。</li><li>目的操作数中NZ矩阵每一行的起始地址为dst_temp_n_addr。</li><li>在每一行中，以16个数据为粒度进行数据块切分，源操作数每一块数据块的起始地址为src_block_addr，目的操作数中每一数据块起始地址为dst_block_addr。</li></ul><p>以下参数为NZ2NZ用户可配置参数，含义及取值范围参见<a href="../cube_compute_store/Fixpipe_L0CToGM.html">Fixpipe搬运参数</a>：</p><ul><li>mSize与nSize分别表示矩阵M方向和N方向上的维度。</li><li>srcStride表示源NZ矩阵中不同Z分形列的间隔，单位为C0_Size（C0_Size=16*sizeof(T)，T为操作数的数据类型）。</li><li>dstStride表示目标NZ矩阵中不同Z分形列的间隔，单位为element。</li></ul></div><h2 id="特性约束">特性约束<a class="header-anchor" href="#特性约束">​</a></h2><ul><li>当NZ2NZ与F32 Channel Split特性组合开启时，搬出到GM的NZ分形中的小分形维度为16*8，确保小z分形的大小为512B。</li><li>对于B8数据类型NZ输出时，Channel Merge默认开启，搬出GM/L1 Buffer小分形维度为16*32，确保小z分形的大小为512B。</li><li>对于B4数据类型NZ输出时，Channel Merge默认开启，搬出GM/L1 Buffer小分形维度为16*64，确保小z分形的大小为512B。</li><li>目标操作数地址之间不能重叠。</li></ul><h2 id="使用示例">使用示例<a class="header-anchor" href="#使用示例">​</a></h2><p>如下图所示，在L0C Buffer中有一个NZ格式的矩阵，该矩阵N方向上维度为48，M方向上维度为24，经过NZ2NZ转换，将数据格式变为右部分所示排布。</p><div data-filter="A3,910b"><p><strong>图1</strong> NZ2NZ示意图（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>）<span id="zh-cn_topic_0000002515820868_fig199191646174210"></span></p><p><img src="`+c+'" alt></p><p>示意图中参数设置示例（通过Fixpipe接口搬运并去除dummy数据）和解释说明如下：</p><ul><li>当M方向上的数据元素个数不是16的倍数时，搬入时会额外读取dummy数据，并在写入目标位置后丢弃这些dummy数据。矩阵块被定义为连续的16*16的数据块，数据块的个数为M/16向上取整，矩阵块的长度为M*16*sizeof(T)，T是数据类型。</li><li>nSize=48，表示源NZ矩阵中待搬运矩阵在N方向上的大小为48个元素。</li><li>mSize=24，表示源NZ矩阵中待搬运矩阵在M方向上的大小为24个元素。</li><li>srcStride=64，表示源NZ矩阵中待搬运矩阵相邻Z排布的起始地址偏移，即下图中第一个Z排布的起始地址与第二个Z排布的起始地址之间的间隔为64 * C0_Size。</li><li>dstStride = 40，表示目的NZ矩阵中相邻Z排布的起始地址偏移，即下图中第一个Z排布的起始地址与第二个Z排布的起始地址之间的间隔为40*32字节。</li></ul></div><div data-filter="950"><p><strong>图2</strong> NZ2NZ示意图（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>）<span id="zh-cn_topic_0000002515820868_fig199191646174233"></span></p><p><img src="'+e+'" alt></p><p>示意图中参数设置示例（通过Fixpipe接口搬运并去除dummy数据）和解释说明如下：</p><ul><li>当M方向上的数据元素个数不是16的倍数时，搬入时会额外读取dummy数据，并在写入目标位置后丢弃这些dummy数据。矩阵块被定义为连续的16*16的数据块，数据块的个数为M/16向上取整，矩阵块的长度为M*16*sizeof(T)，T是数据类型。</li><li>nSize=48，表示源NZ矩阵中待搬运矩阵在N方向上的大小为48个元素。</li><li>mSize=24，表示源NZ矩阵中待搬运矩阵在M方向上的大小为24个元素。</li><li>srcStride=64，表示源NZ矩阵中待搬运矩阵相邻Z排布的起始地址偏移，即下图中第一个Z排布的起始地址与第二个Z排布的起始地址之间的间隔为64 * C0_Size。</li><li>dstStride = 40 * 16，表示目的NZ矩阵中相邻Z排布的起始地址偏移，即下图中第一个Z排布的起始地址与第二个Z排布的起始地址之间的间隔为40*16个元素。</li></ul></div></article></div>',1)])])}const u=a(i,[["render",t]]);export{Z as __pageData,u as default};
